export const labById=id=>ADVANCED_LABS.find(x=>x.id===id)||ADVANCED_LABS[0];
export function freshAdvancedLab(id='hemato'){return {id:labById(id).id,step:0,mode:'normal',wrong:0,hint:false,answer:null,completed:false,feedback:''};}
export function advanceAdvancedLab(s){const l=labById(s.id);if(s.completed||s.step>=l.steps.length)return s;return {...s,step:s.step+1,feedback:l.steps[s.step]};}
export function chooseAdvancedMode(s,mode){if(!['normal','abnormal'].includes(mode))return s;return {...freshAdvancedLab(s.id),mode,wrong:s.wrong,hint:s.hint};}
export function answerAdvancedLab(s,pick){const l=labById(s.id);if(s.step<l.steps.length||s.completed||!Number.isInteger(pick)||pick<0||pick>=l.options.length)return s;
 if(pick===l.correct)return {...s,answer:pick,completed:true,feedback:l.why};
 return {...s,wrong:Math.min(5,s.wrong+1),feedback:'Ainda não. '+l.error};}
export function advancedLabXP(s){return s.completed?Math.max(15,35-5*s.wrong-(s.hint?5:0)):0;}
const t=(x,y,label,color='#d8eff5',size=14)=>`<text x="${x}" y="${y}" fill="${color}" font-size="${size}" font-weight="650" font-family="Inter,system-ui,sans-serif">${esc(label)}</text>`;
const disc=(x,y,r,fill,stroke='#c7e9f1')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${fill}" stroke="${stroke}" stroke-width="3"/>`;
const line=(x1,y1,x2,y2,color='#7ce1d6',w=5)=>`<path d="M${x1} ${y1}L${x2} ${y2}" stroke="${color}" stroke-width="${w}" stroke-linecap="round" fill="none"/>`;
const arrow=(x,y,color='#76decf')=>`<path d="M${x-10} ${y-6}L${x} ${y}L${x-10} ${y+6}" stroke="${color}" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" fill="none"/>`;
const rbc=(x,y)=>`<ellipse cx="${x}" cy="${y}" rx="29" ry="26" fill="#d66d7d" stroke="#ffbec5" stroke-width="4"/><ellipse cx="${x}" cy="${y}" rx="12" ry="10" fill="#a93d5e" opacity=".55"/>`;
function artHemato(s){return `${t(43,56,'ESFREGAÇO · DIFERENCIAL')}${disc(170,174,89,'#e6dfe9')}${disc(168,168,58,'#faf6f9','#d2b4c9')}${[[-17,0],[3,-15],[21,8],[0,25]].map(([a,b])=>`<ellipse cx="${168+a}" cy="${164+b}" rx="15" ry="18" fill="#70628e" stroke="#a795bd" stroke-width="2"/>`).join('')}${t(90,300,'Neutrófilo segmentado')}${line(360,100,360,275,'#355f75',2)}${t(410,92,'LEUCOGRAMA')}${t(408,141,s.mode==='normal'?'6.000 leucócitos/µL':'3.000 leucócitos/µL','#e6f4fa',20)}${t(408,180,s.mode==='normal'?'60% neutrófilos':'20% neutrófilos','#8febdf',18)}${s.step>=2?t(408,229,s.mode==='normal'?'ANC = 3.600/µL':'ANC = 600/µL',s.mode==='normal'?'#a1f5d5':'#ffbaaf',22):t(408,229,'ANC = ? · calcule','#cddfe8',17)}${s.step>=3?t(410,273,s.mode==='normal'?'Padrão sem neutropenia':'Neutropenia moderada','#f7c884',16):''}`;}
function artPhago(s){const step=s.step;return `${t(35,48,'TECIDO · RECONHECIMENTO E RESPOSTA')}${disc(230,170,112,'#417c88','#94e5e1')}${disc(192,150,38,'#304b78','#8fc3dc')}${disc(295,195,18,'#98d4e8','#d3f0ff')}${disc(260,125,15,'#98d4e8','#d3f0ff')}${step>=2?`<ellipse cx="298" cy="163" rx="48" ry="35" fill="#113c55" stroke="#f0d38a" stroke-width="4" stroke-dasharray="7 5"/>`:''}<g class="il52-microbe ${step>=2?'captured':''}">${disc(step>=2?299:498,step>=2?163:160,27,'#d8a6e6','#ffd4fa')}${disc(step>=2?304:504,step>=2?156:153,6,'#74428d','#ba8bcd')}</g>${step>=1?`<path d="M345 151Q391 103 445 146" stroke="#e4d69a" stroke-width="8" fill="none" stroke-dasharray="10 10"/>`:''}${step>=3&&s.mode==='normal'?`${disc(299,163,10,'#d8f19b','#fff')}${t(405,260,'Destruição intracelular')}`:step>=3?`${t(400,260,'Burst oxidativo reduzido','#ffb7ac')}`:''}${t(80,310,'Fagócito · fagossomo')}${t(445,207,'Bactéria sintética')}`;}
function artComplement(s){return `${t(30,46,'TRÊS ROTAS DE ATIVAÇÃO')}${[['Clássica',51],['Lectinas',264],['Alternativa',477]].map(([label,x])=>`<rect x="${x}" y="80" width="180" height="64" rx="12" fill="#214d65" stroke="#4b8c9d"/>${t(x+18,119,label)}`).join('')}${[140,354,570].map(x=>`${line(x,144,354,204,'#5ad4c7',3)}`).join('')}${arrow(355,206)}${disc(355,236,35,s.mode==='normal'?'#259f8b':'#9c566d','#8de5d7')}${t(340,243,'C3','#fff',20)}${s.step>=2?t(407,238,s.mode==='normal'?'Ativado':'Deficiente',s.mode==='normal'?'#abf3db':'#ffc0c0'):''}${s.step>=3?`${t(55,330,s.mode==='normal'?'C3b: opsonização · C3a/C5a: inflamação':'Opsonização prejudicada na ausência de C3',s.mode==='normal'?'#9de9d6':'#ffc1b3',17)}`:''}`;}
function artMhc(s){return `${t(47,49,'SINAPSE IMUNOLÓGICA · pMHC II / TCR')}${disc(190,182,99,'#6a629b','#c3b5ea')}${disc(158,166,31,'#4a4f7e','#a7a1cf')}${disc(570,178,101,'#326c99','#9bc6ef')}${disc(569,166,38,'#28507f','#9bd3f8')}${t(114,313,'Célula dendrítica')}${t(520,313,'T CD4+')}${s.step>=2?`<path d="M286 147L317 147L331 163L317 180L286 180" fill="#f3e7fb" stroke="#7ae0e2" stroke-width="4"/>${line(382,152,352,177,'#6fe5db',8)}${t(297,123,'pMHC II')}${t(380,135,'TCR')}`:''}${s.step>=3&&s.mode==='normal'?`${line(326,240,384,240,'#f7d99a',6)}${t(300,274,'CD80/86–CD28','#f7d99a')}`:s.step>=3?t(299,269,'Coestimulação ausente','#ffb3b0'):''}`;}
function artIgg(s){return `${t(35,46,'RECONHECIMENTO ESPECÍFICO')}${disc(195,177,87,'#a96372','#efb6ba')}${[0,1,2,3,4,5].map(i=>{const a=i*Math.PI/3;return disc(195+Math.cos(a)*67,177+Math.sin(a)*67,11,'#d99376','#ffd1b0')}).join('')}${t(100,304,'Antígeno viral')}${line(490,260,490,168,'#83e7d5',21)}${line(490,168,428,109,'#83e7d5',20)}${line(490,168,552,109,'#83e7d5',20)}${t(470,305,'IgG')}${t(401,88,'Parátopo (Fab)')}${s.step>=2?`${disc(s.mode==='normal'?417:391,100,13,s.mode==='normal'?'#f5d18c':'#a4b1bd','#fff')}${t(304,175,s.mode==='normal'?'Encaixe compatível':'Sem encaixe estável',s.mode==='normal'?'#a6f2db':'#ffb4b4')}`:''}${s.step>=3?t(345,343,s.mode==='normal'?'Neutralização dependente do epítopo':'Neutralização não demonstrada','#d0e3e9',14):''}`;}
function artELISA(s){return `${t(55,50,'MICROPLACA · ELISA INDIRETO DIDÁTICO')}${[['Amostra',178],['CTRL +',358],['CTRL −',538]].map(([label,x],i)=>`${disc(x,180,60,s.step>=3?(i===2&&s.mode==='normal'?'#dbe9ee':s.mode==='abnormal'?'#dca94f':'#dca94f'):'#e9f2f4','#96b5c2')}${disc(x,180,43,s.step>=3?(i===2&&s.mode==='normal'?'#e3f0f2':'#c58f37'):'#f4fafb','#c5d9df')}${t(x-34,282,label,'#d9eaf2')}`).join('')}${s.step>=2?t(248,338,'Antígeno → anticorpo → conjugado + substrato') : t(248,338,'Inclua controles antes da leitura')}${s.step>=3&&s.mode==='abnormal'?t(445,86,'CTRL − REAGENTE · INVÁLIDO','#ffb4aa',13):''}`;}
function artABO(s){const result=s.mode==='normal'?[false,true,false]:[true,true,true];return `${t(50,48,'CARTÃO DE TIPAGEM DIRETA · ABO / RhD')}${[['Anti-A',158],['Anti-B',361],['Anti-D',566]].map(([label,x],i)=>`<rect x="${x-83}" y="105" width="164" height="160" rx="19" fill="#edf4f5" stroke="#a4c3cd" stroke-width="4"/>${t(x-31,94,label)}${s.step>=2?Array.from({length:13},(_,j)=>{const a=j*2.4,r=10+(j%5)*9;return disc(Math.round(x+Math.cos(a)*r),Math.round(187+Math.sin(a)*r),(s.step>=3&&result[i]?j%3===0?9:7:4),s.step>=3&&result[i]?'#a14e65':'#c27d8a','#d7a6ad');}).join(''):disc(x,184,45,'#edb1bb','#fafafa')}${t(x-25,286,s.step<3?'Reagente':result[i]?'AGLUTINA':'NÃO',s.step>=3?result[i]?'#9de8cb':'#ffcfbd':'#cce2eb')}`).join('')}${s.step>=3?t(247,339,s.mode==='normal'?'Tipagem direta: B RhD negativo':'Controles / discrepância: investigar','#deeef2',17):''}`;}
function artLatex(s){return `${t(35,49,'LÁTEX ANTI-PCR · LEITURA VISUAL')}${[150,370,590].map((x,i)=>`${disc(x,181,67,'#ecf3f4','#9bb6bd')}${Array.from({length:27},(_,j)=>{const a=j*2.399,r=s.step>=3 && (s.mode==='abnormal'?i===2:i===1)?(j%5)*3+10:(j%6)*9+7;return disc(Math.round(x+Math.cos(a)*r),Math.round(181+Math.sin(a)*r),s.step>=3 &&(s.mode==='abnormal'?i===2:i===1)?4:2,'#506f84','#83a4b4');}).join('')}${t(x-40,291,`Campo ${i+1}`)}`).join('')}${s.step>=3?t(180,332,s.mode==='abnormal'?'Campo 3 reagente · identidade da amostra desconhecida':'Controles rotulados permitem interpretação','#e4f2f5',16):''}`;}
function artVaccine(s){const pts=(second=false)=>[0,1,2,3,4,5,6].map((i)=>`${100+i*85},${second?260-Math.max(0,Math.sin(i*.52))*145:260-Math.max(0,Math.sin(i*.53))*66}`).join(' ');return `${t(40,50,'RESPOSTA ADAPTATIVA · MODELO QUALITATIVO')}${line(78,300,690,300,'#91b9c9',3)}${line(78,100,78,300,'#91b9c9',3)}${t(27,93,'Resposta')}${t(660,330,'Tempo')}${s.step>=1?`<polyline points="${pts()}" fill="none" stroke="#7fc8ed" stroke-width="6" stroke-linejoin="round" class="il52-curve"/>${t(136,261,'Primária')}`:''}${s.step>=3?`<polyline points="${pts(s.mode==='normal')}" fill="none" stroke="${s.mode==='normal'?'#6bdfc3':'#e4a49d'}" stroke-width="7" stroke-linejoin="round" class="il52-curve"/>${t(440,98,s.mode==='normal'?'Resposta de memória':'Resposta atenuada',s.mode==='normal'?'#9cf3df':'#ffbfb6')}`:''}${t(94,342,'Esquema ilustrativo: sem escala cinética ou quantitativa')}`;}
export const advancedGraphic=(state)=>{const arts={hemato:artHemato,phago:artPhago,complement:artComplement,mhc:artMhc,igg:artIgg,elisa:artELISA,abo:artABO,latex:artLatex,vaccine:artVaccine};return `<svg viewBox="0 0 760 380" role="img" aria-label="Representação biomédica esquemática de ${esc(labById(state.id).name)}" xmlns="http://www.w3.org/2000/svg"><rect x="0" y="0" width="760" height="380" rx="22" fill="#102f45"/>${arts[state.id](state)}</svg>`;};
function advancedOptionReview(lab,state){if(!state.completed)return '';const picked=state.answer;return `<div class="il52-option-review"><h4>Por que sim e por que não</h4>${lab.options.map((label,i)=>`<article class="${i===lab.correct?'right':i===picked?'picked':''}"><b>${String.fromCharCode(65+i)} · ${esc(label)}</b><p>${i===lab.correct?esc(lab.why):esc('Esta opção não é a melhor porque não explica de forma suficiente a observação-chave da estação nem o mecanismo central apresentado em “Análise do experimento”.')}</p></article>`).join('')}</div>`;}
export function renderAdvancedLab(s,profile='Doutor',earned=0){const lab=labById(s.id);return `<section class="il52" aria-label="ImunoLab Clinical 5.2"><div class="il52-head"><div><span class="clinical-overline">IMUNOLAB · EXPERIÊNCIA DE MECANISMOS</span><h2>Seu próximo experimento, ${esc(profile)}</h2><p>Observe, manipule, compare e explique — a resposta correta precisa ser sustentada pelo mecanismo.</p></div><span class="il52-status">${earned} XP registrados na estação</span></div><nav class="il52-picker" aria-label="Selecionar estação">${ADVANCED_LABS.map(l=>`<button data-clinic-action="advanced-select:${l.id}" class="${s.id===l.id?'active':''}" aria-pressed="${s.id===l.id}"><small>${l.track} · ${esc(l.domain)}</small><b>${esc(l.name)}</b></button>`).join('')}</nav><div class="il52-flow">${lab.steps.map((step,i)=>`<div class="${i<s.step?'done':i===s.step?'active':''}"><span>${String(i+1).padStart(2,'0')}</span><b>${esc(step)}</b></div>`).join('')}</div><div class="il52-workspace"><aside class="il52-sidebar"><span class="clinical-overline">${esc(lab.track)} · ${esc(lab.tag)}</span><h3>${esc(lab.name)}</h3><p>${esc(lab.objective)}</p><div class="il52-tasklist">${lab.steps.map((x,i)=>`<div class="${i<s.step?'complete':i===s.step?'active':''}"><span>${i<s.step?'✓':String(i+1).padStart(2,'0')}</span><p>${esc(x)}</p></div>`).join('')}</div><p class="il52-guard">Figura esquemática e valores fictícios; não substituem exames ou recomendações clínicas reais.</p></aside><div class="il52-center"><div class="il52-visual"><div class="il52-visual-head"><span>VISUALIZAÇÃO DO MECANISMO</span><small>${s.step} de ${lab.steps.length} etapas</small></div>${advancedGraphic(s)}</div><div class="il52-controls"><div class="il52-mode" role="group" aria-label="Comparação experimental"><button data-clinic-action="advanced-mode:normal" aria-pressed="${s.mode==='normal'}" class="${s.mode==='normal'?'active':''}">Controle fisiológico</button><button data-clinic-action="advanced-mode:abnormal" aria-pressed="${s.mode==='abnormal'}" class="${s.mode==='abnormal'?'active':''}">Perturbação</button></div><button class="clinical-btn" data-clinic-action="advanced-next" ${s.step>=lab.steps.length?'disabled':''}>${s.step>=lab.steps.length?'Etapas concluídas':'Executar próxima etapa →'}</button><button class="clinical-btn secondary" data-clinic-action="advanced-reset">Reiniciar</button></div><div class="il52-observation" role="status"><strong>${s.mode==='normal'?'Condição fisiológica':'Condição alterada'} · ${s.step>=lab.steps.length?'Resultado observado':'Investigação em andamento'}</strong><p>${esc(s.step>=lab.steps.length?(s.mode==='normal'?lab.normal:lab.abnormal):s.feedback||lab.observe)}</p></div><div class="il52-challenge"><span class="clinical-overline">TRANSFERÊNCIA E RACIOCÍNIO</span><h3>${esc(lab.q)}</h3>${lab.options.map((v,i)=>`<button class="il52-answer ${s.completed&&i===s.answer?'correct':''}" data-clinic-action="advanced-answer:${i}" ${s.step<lab.steps.length||s.completed?'disabled':''}><span>${String.fromCharCode(65+i)}</span>${esc(v)}</button>`).join('')}${s.step<lab.steps.length?'<small>Execute as três etapas antes de responder.</small>':''}${s.step===lab.steps.length&&!s.completed?`<button class="il52-hint" data-clinic-action="advanced-hint">${s.hint?'Dica: '+esc(lab.observe):'Precisa de uma pista? (reduz bônus)'}</button>`:''}${s.feedback&&s.step>=lab.steps.length?`<div class="il52-feedback ${s.completed?'good':'review'}" role="status">${esc(s.feedback)}${s.completed?` · +${advancedLabXP(s)} XP de prática${earned?' (bônus já registrado)':''}.`:''}</div>`:''}${advancedOptionReview(lab,s)}</div></div><aside class="il52-explain"><span class="clinical-overline">ANÁLISE DO EXPERIMENTO</span><h3>Interpretação orientada</h3>${[['01 · OBSERVE',lab.observe],['02 · MECANISMO',lab.mechanism],['03 · SE HOUVER FALHA',lab.failure],['04 · APLICAÇÃO CLÍNICA',lab.application]].map(([head,txt],i)=>`<details class="il52-explain-item" ${i===0||s.step>=i?'open':''}><summary>${esc(head)}</summary><p>${esc(txt)}</p></details>`).join('')}<div class="il52-mistake"><strong>Erro de raciocínio comum</strong><p>${esc(lab.error)}</p></div><div class="il52-competency"><small>DOMÍNIO FORMATIVO</small><b>${esc(lab.domain)}</b><span>XP limitado à primeira conclusão correta de cada estação. Não equivale à avaliação oficial.</span></div></aside></div></section>`;}
